ScriptEditorBase *ShaderTextEditor::create_editor(const Ref<Resource> &resource) {
	// Check class name for Shader to ensure it is not a VisualShader even when the visual shader module is disabled
	if (resource->is_class("Shader") || Object::cast_to<ShaderInclude>(*resource)) {
		return memnew(ShaderTextEditor);
	}
	return nullptr;
}
